const item = $input.first().json;
const meta = { started_at: Date.now(), request_id: String($execution.id) };
let action = '_unknown';

const SPEC = {
  get_faq:                    { req: ['query'],                                                      opt: [] },
  check_availability:         { req: ['service', 'date', 'time'],                                    opt: [] },
  book_appointment:           { req: ['service', 'date', 'time', 'customer_name', 'customer_phone'], opt: ['customer_email'] },
  cancel_appointment:         { req: ['customer_phone', 'appointment_date'],                         opt: ['service', 'appointment_time'] },
  get_current_datetime:       { req: [],                                                             opt: [] },
  check_package_availability: { req: ['service', 'start_date', 'session_time'],                      opt: ['days_of_week'] },
  book_package_appointment:   { req: ['service', 'start_date', 'session_time', 'customer_name', 'customer_phone'], opt: ['customer_email', 'days_of_week'] },
};
class V extends Error { constructor(http, category, msg) { super(msg); this.http = http; this.category = category; } }

const isDate = s => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s); if (!m) return false;
  const [y, mo, d] = [+m[1], +m[2], +m[3]], dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
};
const normTime = s => {
  const m = /^(\d{1,2}):(\d{2})$/.exec(s);
  if (!m || +m[1] > 23 || +m[2] > 59) return null;
  return String(+m[1]).padStart(2, '0') + ':' + m[2];
};

try {
  const ct = String(item.headers?.['content-type'] ?? '').toLowerCase();
  if (!ct.startsWith('application/json')) throw new V(415, 'unsupported_media_type', 'Unsupported content type.');
  const b = item.body;
  if (!b || typeof b !== 'object' || Array.isArray(b)) throw new V(400, 'bad_request', 'The request body must be a JSON object.');

  const a = typeof b.action === 'string' ? b.action.trim() : '';
  if (!Object.prototype.hasOwnProperty.call(SPEC, a)) throw new V(400, 'invalid_action', 'Unsupported action.');
  action = a;
  const spec = SPEC[a];
  const allowed = new Set(['action', 'business_id', ...spec.req, ...spec.opt]);
  for (const k of Object.keys(b)) if (!allowed.has(k)) throw new V(400, 'unexpected_field', 'The request contained an unexpected field.');

  const take = (k, required, max) => {
    let v = b[k];
    if (v === undefined || v === null || v === '') { if (required) throw new V(400, 'missing_field', `${k} is required.`); return undefined; }
    if (typeof v !== 'string') throw new V(400, 'bad_type', `${k} must be a string.`);
    v = v.normalize('NFKC').replace(/\s+/g, ' ').trim();
    if (v === '') { if (required) throw new V(400, 'missing_field', `${k} is required.`); return undefined; }
    if (v.length > max) throw new V(400, 'too_long', `${k} is too long.`);
    if (/[\u0000-\u001F\u007F]/.test(v)) throw new V(400, 'bad_chars', `${k} contains invalid characters.`);
    return v;
  };

  const business_id = take('business_id', true, 64);
  if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(business_id)) throw new V(400, 'bad_business_id', 'business_id is not valid.');
  const req = { action, business_id };

  const MAX = { query: 500, customer_email: 254, customer_name: 80, service: 100, customer_phone: 25, date: 10, appointment_date: 10, time: 5, appointment_time: 5, start_date: 10, session_time: 5, days_of_week: 27 };
  for (const k of [...spec.req, ...spec.opt]) {
    let v = take(k, spec.req.includes(k), MAX[k]);
    if (v === undefined) continue;
    if (k === 'date' || k === 'appointment_date') {
      if (!isDate(v)) throw new V(400, 'bad_date', `${k} must be a real date in YYYY-MM-DD format.`);
    } else if (k === 'time' || k === 'appointment_time') {
      v = normTime(v); if (!v) throw new V(400, 'bad_time', `${k} must be a 24-hour time in HH:mm format.`);
    } else if (k === 'customer_phone') {
      const digits = v.replace(/\D/g, '');
      if (!/^[+\d\s().-]+$/.test(v) || digits.length < 7 || digits.length > 16) throw new V(400, 'bad_phone', 'customer_phone is not a valid phone number.');
    } else if (k === 'customer_email') {
      v = v.toLowerCase();
      if (!/^[^\s@]{1,64}@[^\s@]+\.[^\s@]{2,}$/.test(v)) throw new V(400, 'bad_email', 'customer_email is not a valid email address.');
    } else if (k === 'customer_name') {
      if (!/^[\p{L}\p{M}][\p{L}\p{M} .'\u2019-]{1,79}$/u.test(v)) throw new V(400, 'bad_name', 'customer_name is not valid.');
    } else if (k === 'service') {
      if (!/^[\p{L}\p{N} &'\u2019()\/.,+-]{1,100}$/u.test(v)) throw new V(400, 'bad_service', 'service is not valid.');
    } else if (k === 'start_date') {
      if (!isDate(v)) throw new V(400, 'bad_date', 'start_date must be a real date in YYYY-MM-DD format.');
    } else if (k === 'session_time') {
      v = normTime(v); if (!v) throw new V(400, 'bad_time', 'session_time must be a 24-hour time in HH:mm format.');
    } else if (k === 'days_of_week') {
      v = v.toLowerCase().replace(/\s+/g, '');
      const parts = v.split(',');
      const valid = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
      if (parts.length === 0 || parts.length > 7 || !parts.every(p => valid.includes(p)) || new Set(parts).size !== parts.length) {
        throw new V(400, 'bad_days_of_week', 'days_of_week must be a comma-separated list of mon,tue,wed,thu,fri,sat,sun with no repeats.');
      }
    }
    req[k] = v;
  }
  return [{ json: { meta, req } }];
} catch (e) {
  const v = e instanceof V ? e : new V(500, 'internal_error', 'Something went wrong.');
  return [{ json: { meta, res: { action, http: v.http, category: v.category, msg: v.message } } }];
}

const { req, meta } = $('Validate Request').first().json;

const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];
const UNAVAILABLE = "I'm unable to help with that right now.";

const normalizeRow = (obj) => {
  const out = {};
  for (const [k, v] of Object.entries(obj ?? {})) {
    const nk = String(k).trim().toLowerCase().replace(/[\s\-]+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (nk && !(nk in out)) out[nk] = v;
  }
  return out;
};

const rows = $input.all()
  .map(i => normalizeRow(i.json))
  .filter(r => String(r?.business_id ?? '').trim() === req.business_id);

if (rows.length === 0) return fail(404, 'unknown_business', UNAVAILABLE);
if (rows.length > 1) return fail(404, 'duplicate_business_row', UNAVAILABLE);

const row = rows[0];
const s = k => String(row[k] ?? '').trim();

for (const k of ['business_name','timezone','google_services_sheet_id','google_faqs_sheet_id','google_calendar_id','business_hours','booking_enabled','default_country_calling_code']) {
  if (!s(k)) return fail(404, 'incomplete_config', UNAVAILABLE);
}

const tz = s('timezone');
if (!DateTime.now().setZone(tz).isValid) return fail(404, 'bad_timezone', UNAVAILABLE);
if (!/^[A-Za-z0-9_-]{20,120}$/.test(s('google_services_sheet_id'))) return fail(404, 'bad_services_sheet_id', UNAVAILABLE);
if (!/^[A-Za-z0-9_-]{20,120}$/.test(s('google_faqs_sheet_id'))) return fail(404, 'bad_faqs_sheet_id', UNAVAILABLE);
if (!/^[A-Za-z0-9._%+@-]{3,200}$/.test(s('google_calendar_id'))) return fail(404, 'bad_calendar_id', UNAVAILABLE);

const cc = s('default_country_calling_code');
if (!/^\d{1,3}$/.test(cc)) return fail(404, 'bad_calling_code', UNAVAILABLE);

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

function parseHours(str) {
  const out = {};
  DAYS.forEach(d => out[d] = []);
  const seen = new Set();
  for (const part of str.toLowerCase().split(';').map(x => x.trim()).filter(Boolean)) {
    const [d, rest] = part.split('=').map(x => x.trim());
    if (!DAYS.includes(d) || seen.has(d) || rest === undefined) return null;
    seen.add(d);
    if (rest === 'closed') continue;
    for (const r of rest.split(',')) {
      const m = /^(\d{2}):(\d{2})-(\d{2}):(\d{2})$/.exec(r.trim());
      if (!m) return null;
      const a = +m[1] * 60 + +m[2], z = +m[3] * 60 + +m[4];
      if (+m[1] > 23 || +m[3] > 23 || +m[2] > 59 || +m[4] > 59 || a >= z) return null;
      out[d].push([a, z]);
    }
    out[d].sort((x, y) => x[0] - y[0]);
    for (let i = 1; i < out[d].length; i++) if (out[d][i][0] < out[d][i - 1][1]) return null;
  }
  return seen.size === 7 ? out : null;
}

const hours = parseHours(s('business_hours'));
if (!hours) return fail(404, 'bad_hours', UNAVAILABLE);

const num = (k, def, min, max) => {
  if (s(k) === '') return def;
  const n = Number(s(k));
  return Number.isInteger(n) && n >= min && n <= max ? n : NaN;
};

const slot_interval = num('slot_interval_minutes', 30, 5, 240);
const min_notice = num('min_notice_minutes', 0, 0, 10080);
const max_advance_days = num('max_advance_days', 90, 1, 730);
if ([slot_interval, min_notice, max_advance_days].some(Number.isNaN)) return fail(404, 'bad_numeric_config', UNAVAILABLE);

const booking_enabled = ['true', 'yes', '1'].includes(s('booking_enabled').toLowerCase());
if (!booking_enabled && (req.action === 'check_availability' || req.action === 'book_appointment' || req.action === 'check_package_availability' || req.action === 'book_package_appointment')) {
  return fail(200, 'booking_disabled', 'Online booking is not available for this business right now.');
}

const normPhone = raw => {
  let d = raw.replace(/[^\d+]/g, '');
  if ((d.match(/\+/g) || []).length > 1 || (d.includes('+') && d[0] !== '+')) return null;
  if (d.startsWith('00')) d = '+' + d.slice(2);
  else if (d.startsWith('0')) d = '+' + cc + d.slice(1);
  else if (!d.startsWith('+')) return null;
  if (d.startsWith('+' + cc + '0')) d = '+' + cc + d.slice(cc.length + 2);
  return /^\+[1-9]\d{7,14}$/.test(d) ? d : null;
};

const req2 = { ...req };
if (req.customer_phone) {
  req2.customer_phone = normPhone(req.customer_phone);
  if (!req2.customer_phone) return fail(400, 'bad_phone', 'customer_phone is not a valid phone number. Please include the country code.');
}

return [{ json: { meta, req: req2, cfg: {
  business_id: req.business_id, name: s('business_name'), tz,
  services_sheet_id: s('google_services_sheet_id'), faqs_sheet_id: s('google_faqs_sheet_id'), calendar_id: s('google_calendar_id'),
  hours, slot_interval, min_notice, max_advance_days, cc
} } }];

const { req, cfg, meta } = $('Validate Business').first().json;
const yes = v => ['true', 'yes', '1'].includes(String(v ?? '').trim().toLowerCase());

const normalizeRow = (obj) => {
  const out = {};
  for (const [k, v] of Object.entries(obj ?? {})) {
    const nk = String(k).trim().toLowerCase().replace(/[\s\-]+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (nk && !(nk in out)) out[nk] = v;
  }
  return out;
};

const rows = $input.all().map(i => normalizeRow(i.json)).filter(r => String(r.question ?? '').trim() && String(r.answer ?? '').trim() && yes(r.active));

const STOP = new Set('a an the is are am was were be do does did i you we me my your our it its of to for in on at and or can could would will what whats how when where which who whom this that there any about tell please have has get with from as if by not no yes'.split(' '));
const tok = t => String(t).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/).filter(w => w.length > 1 && !STOP.has(w)).map(w => (w.length > 3 && w.endsWith('s') ? w.slice(0, -1) : w));

const q = new Set(tok(req.query));
const NOT_FOUND = "I don't have that information available right now.";
let best = null;
if (q.size) {
  for (const r of rows) {
    const qt = new Set(tok(`${r.question} ${r.category ?? ''}`)), at = new Set(tok(r.answer));
    let score = 0, qHits = 0;
    for (const w of q) { if (qt.has(w)) { score += 1; qHits++; } else if (at.has(w)) score += 0.4; }
    const cov = score / q.size;
    if (qHits >= 1 && cov >= 0.6 && (!best || score > best.score || (score === best.score && cov > best.cov))) best = { r, score, cov };
  }
}
const body = best ? { success: true, answer: String(best.r.answer).trim().slice(0, 1000) } : { success: false, answer: NOT_FOUND };
return [{ json: { meta, req, res: { action: 'get_faq', http: 200, category: best ? 'ok' : 'faq_no_match', body } } }];

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const { req, cfg, meta } = $('Validate Business').first().json;
const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];
const norm = s => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const yes = v => ['true', 'yes', '1'].includes(norm(v));

const normalizeRow = (obj) => {
  const out = {};
  for (const [k, v] of Object.entries(obj ?? {})) {
    const nk = String(k).trim().toLowerCase().replace(/[\s\-]+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (nk && !(nk in out)) out[nk] = v;
  }
  return out;
};

const rows = $input.all().map(i => normalizeRow(i.json)).filter(r => norm(r.name) && yes(r.active));

const want = norm(req.service);
const hits = rows.filter(r => {
  const serviceName = norm(r.name);
  const aliases = String(r.aliases ?? '').split(/[|,]/).map(norm).filter(Boolean);
  return serviceName === want || aliases.includes(want);
});

if (hits.length === 0) {
  const names = rows.map(r => String(r.name).trim()).slice(0, 10).join(', ');
  return fail(200, 'service_not_found', names ? `I couldn't find that service. Available services: ${names}.` : "I couldn't find that service.");
}
if (hits.length > 1) return fail(503, 'duplicate_service_row', "The requested service has duplicate configuration.");

const service = hits[0];
const svcName = String(service.name).trim();

// FIX #1: a service with session_minutes set is a multi-session PACKAGE — it must never be
// booked through this single-session path (it would otherwise book one unbroken block for
// the full package duration, e.g. one 10-hour sitting). Route it to check_package_availability
// / book_package_appointment instead.
if (String(service.session_minutes ?? '').trim()) {
  return fail(200, 'is_a_package', `${svcName} is a multi-session package — let me check available sessions for it instead of a single slot.`);
}

const duration = Number(service.duration);
if (!Number.isInteger(duration) || duration < 5 || duration > 480) return fail(503, 'bad_service_config', "The requested service is not configured correctly.");

const price = Number(service.price);
if (!Number.isFinite(price) || price < 0) return fail(503, 'bad_service_price', "The requested service price is not configured correctly.");

const tz = cfg.tz;
const start = DateTime.fromISO(`${req.date}T${req.time}`, { zone: tz });
if (!start.isValid) return fail(400, 'bad_datetime', 'That date or time is not valid.');

const wall = d => d.toFormat('yyyy-MM-dd HH:mm');
if (wall(start) !== `${req.date} ${req.time}`) return fail(200, 'nonexistent_local_time', 'That time does not exist on that date because of a clock change. Please choose another time.');
if (wall(start.plus({ minutes: 60 })) === wall(start) || wall(start.minus({ minutes: 60 })) === wall(start)) {
  return fail(200, 'ambiguous_local_time', 'That time is ambiguous because of a clock change. Please choose another time.');
}

const end = start.plus({ minutes: duration });
const now = DateTime.now().setZone(tz);

if (start < now) return fail(200, 'past_time', 'That time has already passed.');
if (start < now.plus({ minutes: cfg.min_notice })) return fail(200, 'too_soon', 'That time is too soon to book. Please choose a later time.');
if (start > now.plus({ days: cfg.max_advance_days })) return fail(200, 'too_far_ahead', 'That date is too far in advance to book.');

const dayKey = DAYS[start.weekday - 1];
if ((cfg.hours[dayKey] ?? []).length === 0) return fail(200, 'closed_day', 'The business is closed on that day.');

const startMinutes = start.hour * 60 + start.minute;
const endMinutes = end.hour * 60 + end.minute;
const openingParts = cfg.hours[dayKey] ?? [];
const fitsBusinessHours = openingParts.some(([open, close]) => startMinutes >= open && endMinutes <= close);
if (!fitsBusinessHours) return fail(200, 'outside_business_hours', 'That appointment would fall outside business hours. Please choose another time.');

const dayStart = start.startOf('day');
const dayEnd = dayStart.plus({ days: 1 }).startOf('day');
const base = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(cfg.calendar_id)}/events`;

return [{ json: { meta, req, cfg,
  svc: { id: String(service.service_id ?? '').trim(), name: svcName, duration, price },
  slot: { startMs: start.toMillis(), endMs: end.toMillis(), startIso: start.toISO(), endIso: end.toISO(), dayKey, parts: { year: start.year, month: start.month, day: start.day } },
  q: { url: base, timeMin: dayStart.toISO(), timeMax: dayEnd.toISO() },
  key_material: [cfg.business_id, req.customer_phone ?? '', norm(svcName), req.date, req.time, now.toISODate()].join('|')
} }];

const c = $('Compute Booking Key').first().json;
const { req, cfg, svc, slot, meta, booking_key } = c;
const list = $input.first().json;
const tz = cfg.tz;
const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];
const norm = s => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const field = (d, k) => { const m = new RegExp('(?:^|\\n|<br\\s*/?>)\\s*' + k + ':\\s*([^\\n<]*)', 'i').exec(String(d ?? '')); return m ? m[1].trim() : ''; };
const fmt = ms => DateTime.fromMillis(ms, { zone: tz }).toFormat('HH:mm');

if (list.nextPageToken) return fail(503, 'calendar_incomplete_data');

const busy = [];
for (const e of list.items ?? []) {
  if (e.status === 'cancelled' || e.transparency === 'transparent') continue;
  if (e.start?.dateTime && e.end?.dateTime) busy.push({ s: Date.parse(e.start.dateTime), e: Date.parse(e.end.dateTime), ev: e });
  else if (e.start?.date && e.end?.date) busy.push({ s: DateTime.fromISO(e.start.date, { zone: tz }).startOf('day').toMillis(), e: DateTime.fromISO(e.end.date, { zone: tz }).startOf('day').toMillis(), ev: e });
  else return fail(503, 'calendar_bad_event_shape');
}

if (req.action === 'book_appointment') {
  const dup = busy.find(b => b.s === slot.startMs && field(b.ev.description, 'Business ID') === cfg.business_id && field(b.ev.description, 'Customer Phone') === req.customer_phone && norm(field(b.ev.description, 'Service')) === norm(svc.name));
  if (dup) return [{ json: { meta, req, res: { action: req.action, http: 200, category: 'idempotent_replay', body: { success: true, message: `Your ${svc.name} appointment is booked for ${req.date} at ${req.time}.`, appointment_id: dup.ev.id } } } }];
}

const DUR = svc.duration * 60000;
const at = m => DateTime.fromObject({ ...slot.parts, hour: Math.floor(m / 60), minute: m % 60 }, { zone: tz }).toMillis();
const spans = (cfg.hours[slot.dayKey] ?? []).map(([a, z]) => [at(a), at(z)]);
const earliest = Date.now() + cfg.min_notice * 60000;
const overlaps = (s, e) => busy.some(b => s < b.e && e > b.s);
const inHours = s => spans.some(([a, z]) => s >= a && s + DUR <= z);
const fits = s => s >= earliest && inHours(s) && !overlaps(s, s + DUR);

const reqFits = fits(slot.startMs);
const step = cfg.slot_interval * 60000, cands = [];
for (const [a, z] of spans) for (let t = a; t + DUR <= z; t += step) if (fits(t)) cands.push(t);
const others = cands.filter(t => t !== slot.startMs).sort((x, y) => Math.abs(x - slot.startMs) - Math.abs(y - slot.startMs)).slice(0, reqFits ? 4 : 5);
const times = [...others, ...(reqFits ? [slot.startMs] : [])].sort((x, y) => x - y).map(fmt);
const tail = times.length ? ` Available times that day: ${times.join(', ')}.` : ' There are no other available times that day.';

if (req.action === 'check_availability') {
  if (reqFits) return [{ json: { meta, req, res: { action: req.action, http: 200, category: 'ok', body: { available: true, available_times: times, message: 'The requested time is available.' } } } }];
  const [cat, m] = !inHours(slot.startMs) ? ['outside_hours', 'That time is outside opening hours.'] : ['slot_unavailable', 'That time is not available.'];
  return [{ json: { meta, req, res: { action: req.action, http: 200, category: cat, body: { available: false, available_times: times, message: m + tail } } } }];
}

if (!reqFits) {
  const [cat, m] = !inHours(slot.startMs) ? ['outside_hours', 'That time is outside opening hours.'] : ['slot_unavailable', 'That time is no longer available.'];
  return fail(200, cat, m + tail);
}
const description = [`Customer Name: ${req.customer_name}`, `Customer Phone: ${req.customer_phone}`, `Customer Email: ${req.customer_email ?? ''}`, `Business ID: ${cfg.business_id}`, `Service: ${svc.name}`].join('\n');
return [{ json: { meta, req, cfg, svc, slot, q: c.q, booking_key, proceed: true, event: { id: booking_key, summary: `${svc.name} - ${req.customer_name}`, description, start: { dateTime: slot.startIso, timeZone: tz }, end: { dateTime: slot.endIso, timeZone: tz } } } }];

const prev = $('Evaluate Slot').first().json;
const { req, meta, booking_key, svc } = prev;
const r = $input.first().json, code = Number(r.statusCode), body = r.body ?? {};
const done = (http, category, extra) => [{ json: { meta, req, res: { action: 'book_appointment', http, category, ...extra } } }];

if (code === 200 && body.status === 'confirmed' && body.id === booking_key) return done(200, 'ok', { body: { success: true, message: `Your ${svc.name} appointment has been booked for ${req.date} at ${req.time}.`, appointment_id: body.id } });
if (code === 409) return [{ json: { ...prev, need_existing: true } }];

const reason = JSON.stringify(body?.error?.errors ?? '');
let category = 'booking_failed';
if (code === 401) category = 'google_auth';
else if (code === 403) category = /rate|quota/i.test(reason) ? 'google_rate_limit' : 'google_auth';
else if (code === 404) category = 'google_calendar_not_found';
else if (code === 429) category = 'google_rate_limit';
else if (code >= 500) category = 'google_unavailable';
return done(503, category, {});

const prev = $('Interpret Insert').first().json;
const { req, meta, cfg, svc, booking_key } = prev;
const r = $input.first().json, code = Number(r.statusCode), ev = r.body ?? {};
const field = (d, k) => { const m = new RegExp('(?:^|\\n|<br\\s*/?>)\\s*' + k + ':\\s*([^\\n<]*)', 'i').exec(String(d ?? '')); return m ? m[1].trim() : ''; };
const done = (http, category, extra) => [{ json: { meta, req, res: { action: 'book_appointment', http, category, ...extra } } }];

if (code === 200 && ev.status === 'confirmed' && ev.id === booking_key && field(ev.description, 'Business ID') === cfg.business_id && field(ev.description, 'Customer Phone') === req.customer_phone) return done(200, 'idempotent_replay', { body: { success: true, message: `Your ${svc.name} appointment is booked for ${req.date} at ${req.time}.`, appointment_id: ev.id } });
if (code === 200 && ev.status === 'cancelled') return done(503, 'id_collision_cancelled_event', {});
return done(503, 'booking_failed', {});

const { req, cfg, meta } = $input.first().json;
const d = DateTime.fromISO(req.appointment_date, { zone: cfg.tz });
const dayStart = d.startOf('day'), dayEnd = dayStart.plus({ days: 1 }).startOf('day');
if (dayEnd.toMillis() <= Date.now()) return [{ json: { meta, req, res: { action: req.action, http: 200, category: 'past_date', msg: 'I can only cancel upcoming appointments.' } } }];
const base = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(cfg.calendar_id)}/events`;
