const list = $input.first().json;
const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];
const norm = s => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const field = (d, k) => { const m = new RegExp('(?:^|\\n|<br\\s*/?>)\\s*' + k + ':\\s*([^\\n<]*)', 'i').exec(String(d ?? '')); return m ? m[1].trim() : ''; };

if (list.nextPageToken) return fail(503, 'calendar_incomplete_data');
const now = Date.now();
const matches = (list.items ?? []).filter(e => {
  if (e.status === 'cancelled' || !e.start?.dateTime) return false;
  const s = Date.parse(e.start.dateTime); if (s < now) return false;
  const st = DateTime.fromMillis(s, { zone: cfg.tz });
  if (st.toISODate() !== req.appointment_date) return false;
  if (field(e.description, 'Business ID') !== cfg.business_id) return false;
  if (field(e.description, 'Customer Phone') !== req.customer_phone) return false;
  if (req.service && norm(field(e.description, 'Service')) !== norm(req.service)) return false;
  if (req.appointment_time && st.toFormat('HH:mm') !== req.appointment_time) return false;
  return true;
});
if (matches.length === 0) return fail(200, 'appointment_not_found', "I couldn't find an appointment matching those details.");
if (matches.length > 1) return fail(200, 'multiple_matches', 'I found more than one appointment on that date. Please tell me the service and the appointment time, or contact the business directly.');
return [{ json: { meta, req, cfg, delete_url: `${p.q.url}/${encodeURIComponent(matches[0].id)}` } }];

const { req, meta } = $('Match Cancellation').first().json;
const r = $input.first().json, code = Number(r.statusCode);
const done = (http, category, extra) => [{ json: { meta, req, res: { action: 'cancel_appointment', http, category, ...extra } } }];
if (code === 204 || code === 200) return done(200, 'ok', { body: { success: true, message: 'The appointment has been cancelled.' } });
if (code === 404 || code === 410) return done(200, 'appointment_not_found', { msg: "I couldn't find that appointment. It may already have been cancelled." });
const reason = JSON.stringify(r.body?.error?.errors ?? '');
let category = 'cancel_failed';
if (code === 401) category = 'google_auth';
else if (code === 403) category = /rate|quota/i.test(reason) ? 'google_rate_limit' : 'google_auth';
else if (code === 429) category = 'google_rate_limit';
else if (code >= 500) category = 'google_unavailable';
return done(503, category, {});

const { req, cfg, meta } = $input.first().json;
const now = DateTime.now().setZone(cfg.tz);
return [{ json: { meta, req, res: { action: 'get_current_datetime', http: 200, category: 'ok', body: {
  success: true,
  date: now.toFormat('yyyy-MM-dd'),
  time: now.toFormat('HH:mm'),
  day_of_week: now.toFormat('EEEE'),
  datetime: now.toFormat('yyyy-MM-dd HH:mm'),
  timezone: cfg.tz
} } } }];

const ctx = (() => { for (const n of ['Validate Business', 'Validate Request']) { try { return $(n).first().json; } catch (e) {} } return {}; })();
const raw = JSON.stringify($input.first().json?.error ?? $input.first().json ?? '').slice(0, 1000);
let category = 'google_unavailable', http = 503;
if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(raw)) { category = 'timeout'; http = 504; }
else if (/429|rate ?limit|quota/i.test(raw)) category = 'google_rate_limit';
else if (/401|invalid_grant|invalid_client|unauthori[sz]ed|authentication/i.test(raw)) category = 'google_auth';
else if (/403|forbidden|404|not found|unable to parse range|permission/i.test(raw)) category = 'google_config_or_permission';
return [{ json: { meta: ctx.meta, req: ctx.req, res: { action: ctx.req?.action ?? '_unknown', http, category } } }];

const j = $input.first().json;
const res = j.res ?? { action: '_unknown', http: 500, category: 'internal_error' };
const a = res.action;
const TECH = {
  get_faq: "I couldn't look that up right now.",
  check_availability: "I couldn't check availability right now.",
  book_appointment: "I couldn't complete the booking right now.",
  cancel_appointment: "I couldn't cancel the appointment right now.",
  get_current_datetime: "I couldn't get the current date and time right now.",
  check_package_availability: "I couldn't check package availability right now.",
  book_package_appointment: "I couldn't complete the package booking right now.",
  _unknown: 'Something went wrong.',
};
const msg = res.msg || TECH[a] || TECH._unknown;
const FAIL = {
  get_faq: () => ({ success: false, answer: msg }),
  check_availability: () => ({ available: false, available_times: [], message: msg }),
  book_appointment: () => ({ success: false, message: msg }),
  cancel_appointment: () => ({ success: false, message: msg }),
  get_current_datetime: () => ({ success: false, message: msg }),
  check_package_availability: () => ({ available: false, sessions: [], message: msg }),
  book_package_appointment: () => ({ success: false, message: msg }),
  _unknown: () => ({ success: false, message: msg }),
};
const SHAPE = {
  get_faq: b => (typeof b.success === 'boolean' && typeof b.answer === 'string') ? { success: b.success, answer: b.answer } : null,
  check_availability: b => (typeof b.available === 'boolean' && Array.isArray(b.available_times) && typeof b.message === 'string') ? { available: b.available, available_times: b.available_times.map(String), message: b.message } : null,
  book_appointment: b => (typeof b.success === 'boolean' && typeof b.message === 'string') ? (b.appointment_id ? { success: b.success, message: b.message, appointment_id: String(b.appointment_id) } : { success: b.success, message: b.message }) : null,
  cancel_appointment: b => (typeof b.success === 'boolean' && typeof b.message === 'string') ? { success: b.success, message: b.message } : null,
  get_current_datetime: b => (typeof b.success === 'boolean' && typeof b.date === 'string' && typeof b.time === 'string') ? { success: b.success, date: b.date, time: b.time, day_of_week: String(b.day_of_week ?? ''), datetime: String(b.datetime ?? ''), timezone: String(b.timezone ?? '') } : null,
  check_package_availability: b => (typeof b.available === 'boolean' && Array.isArray(b.sessions) && typeof b.message === 'string') ? { available: b.available, sessions: b.sessions, message: b.message, ...(b.price !== undefined ? { price: b.price } : {}) } : null,
  book_package_appointment: b => (typeof b.success === 'boolean' && typeof b.message === 'string') ? { success: b.success, message: b.message, ...(Array.isArray(b.sessions) ? { sessions: b.sessions } : {}), ...(b.price !== undefined ? { price: b.price } : {}) } : null,
};
let http = Number(res.http) || 500, category = res.category ?? 'internal_error';
let body = res.body && SHAPE[a] ? SHAPE[a](res.body) : null;
if (!body) {
  if (res.body) { http = 500; category = 'contract_violation'; }
  body = (FAIL[a] ?? FAIL._unknown)();
}
const ok = category === 'ok' || category === 'idempotent_replay';
const log = { ts: new Date().toISOString(), request_id: j.meta?.request_id ?? null, business_id: j.req?.business_id ?? null, action: a, http, outcome: ok ? 'success' : 'failure', category, duration_ms: Date.now() - (j.meta?.started_at ?? Date.now()) };
console.log(JSON.stringify(log));
return [{ json: { http, body, log, persist: a === 'book_appointment' || a === 'book_package_appointment' || a === 'cancel_appointment' || http >= 400 } }];

const business = $('Load Business').first().json;
const evalSlot = $('Evaluate Slot').first().json;
