const b = $('Prepare Notification Data').first().json;
let ai = {};
try {
  ai = JSON.parse($input.first().json.response);
} catch (e) {
  ai = {};
}

const fallback = {
  customer_subject: `Booking Confirmed - ${b.service} at ${b.business_name}`,
  customer_body: `Hi ${b.customer_name},\n\nYour booking is confirmed.\n\nService: ${b.service}\nDate: ${b.date_display}\nTime: ${b.time_display}\nLocation: ${b.business_location}\n\nNeed to reschedule? Call us on ${b.business_phone}.\n\nSee you soon,\n${b.business_name}`,
  owner_subject: `New Booking - ${b.customer_name} (${b.service})`,
  owner_body: `A new booking was made.\n\nCustomer: ${b.customer_name}\nPhone: ${b.customer_phone}\nEmail: ${b.customer_email}\nService: ${b.service}\nDate: ${b.date_display}\nTime: ${b.time_display}\n\nCalendar: ${b.calendar_link}`
};

return [{
  json: {
    ...b,
    customer_subject: ai.customer_subject || fallback.customer_subject,
    customer_body: ai.customer_body || fallback.customer_body,
    owner_subject: ai.owner_subject || fallback.owner_subject,
    owner_body: ai.owner_body || fallback.owner_body
  }
}];

const { req, cfg, meta } = $('Validate Business').first().json;
const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];
const norm = s => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const yes = v => ['true', 'yes', '1'].includes(norm(v));

const normalizeRow = (obj) => {
  const out = {};
  for (const [k, v] of Object.entries(obj ?? {})) {
    const nk = String(k).trim().toLowerCase().replace(/[\s\-]+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (nk && !(nk in out)) out[nk] = v;
  }
  return out;
};

const rows = $input.all().map(i => normalizeRow(i.json)).filter(r => norm(r.name) && yes(r.active));
const want = norm(req.service);
const hits = rows.filter(r => {
  const serviceName = norm(r.name);
  const aliases = String(r.aliases ?? '').split(/[|,]/).map(norm).filter(Boolean);
  return serviceName === want || aliases.includes(want);
});

if (hits.length === 0) {
  const names = rows.map(r => String(r.name).trim()).slice(0, 10).join(', ');
  return fail(200, 'service_not_found', names ? `I couldn't find that service. Available services: ${names}.` : "I couldn't find that service.");
}
if (hits.length > 1) return fail(503, 'duplicate_service_row', 'The requested service has duplicate configuration.');

const service = hits[0];
const svcName = String(service.name).trim();
const s = k => String(service[k] ?? '').trim();

// IMPORTANT: 'duration' must be stored in MINUTES (e.g. 600 for a 10-hour package), same
// column the single-session flow (Resolve Service) already reads. 'session_minutes' is a
// NEW optional column: the max length of one sitting (e.g. 120 for a 2-hour daily lesson).
// Leave session_minutes blank for services that always fit in one sitting.
const durationMin = Number(s('duration'));
if (!Number.isInteger(durationMin) || durationMin < 5 || durationMin > 3000) return fail(503, 'bad_service_config', 'The requested service is not configured correctly.');

let sessionMin = s('session_minutes') ? Number(s('session_minutes')) : durationMin;
if (!Number.isInteger(sessionMin) || sessionMin < 5 || sessionMin > durationMin) return fail(503, 'bad_service_config', 'The requested service session length is not configured correctly.');

const price = Number(s('price'));
if (!Number.isFinite(price) || price < 0) return fail(503, 'bad_service_price', 'The requested service price is not configured correctly.');

const sessionsNeeded = Math.ceil(durationMin / sessionMin);
const lengths = [];
let remaining = durationMin;
for (let i = 0; i < sessionsNeeded; i++) {
  const len = Math.min(sessionMin, remaining);
  lengths.push(len);
  remaining -= len;
}

if (sessionsNeeded <= 1) return fail(200, 'not_a_package', 'That service fits in a single session, so please use the regular booking flow for it instead.');

const tz = cfg.tz;
const start = DateTime.fromISO(req.start_date, { zone: tz });
if (!start.isValid) return fail(400, 'bad_date', 'That start date is not valid.');

const now = DateTime.now().setZone(tz);
if (start.startOf('day') < now.startOf('day')) return fail(200, 'past_date', 'That start date has already passed.');
if (start.startOf('day') > now.plus({ days: cfg.max_advance_days }).startOf('day')) return fail(200, 'too_far_ahead', 'That start date is too far in advance to book.');

let daysFilter = null;
if (req.days_of_week) daysFilter = req.days_of_week.split(',');

// Search window: generous enough to find every session even with a restrictive days_of_week
// filter or business closures, capped by the business's own max_advance_days.
const windowDays = Math.max(14, Math.min(cfg.max_advance_days, sessionsNeeded * 21));
const windowStart = start.startOf('day');
const windowEnd = windowStart.plus({ days: windowDays }).startOf('day');

const base = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(cfg.calendar_id)}/events`;

return [{ json: { meta, req, cfg,
  svc: { name: svcName, durationMin, sessionMin, lengths, price },
  search: { startDate: req.start_date, sessionTime: req.session_time, daysFilter, windowDays },
  q: { url: base, timeMin: windowStart.toISO(), timeMax: windowEnd.toISO() }
} }];

const DAYS = ['mon','tue','wed','thu','fri','sat','sun'];
const p = $('Resolve Package Service').first().json;
const { req, cfg, svc, search, meta } = p;
const list = $input.first().json;
const tz = cfg.tz;
const fail = (http, category, msg) => [{ json: { meta, req, res: { action: req.action, http, category, msg } } }];

if (list.nextPageToken) return fail(503, 'calendar_incomplete_data');

const busy = [];
for (const e of list.items ?? []) {
  if (e.status === 'cancelled' || e.transparency === 'transparent') continue;
  if (e.start?.dateTime && e.end?.dateTime) busy.push({ s: Date.parse(e.start.dateTime), e: Date.parse(e.end.dateTime) });
  else if (e.start?.date && e.end?.date) busy.push({ s: DateTime.fromISO(e.start.date, { zone: tz }).startOf('day').toMillis(), e: DateTime.fromISO(e.end.date, { zone: tz }).startOf('day').toMillis() });
  else return fail(503, 'calendar_bad_event_shape');
}

const [hh, mm] = search.sessionTime.split(':').map(Number);
const earliest = Date.now() + cfg.min_notice * 60000;
const overlaps = (s, e) => busy.some(b => s < b.e && e > b.s);

const windowStart = DateTime.fromISO(search.startDate, { zone: tz }).startOf('day');
const sessions = [];
let idx = 0;

for (let d = 0; d < search.windowDays && idx < svc.lengths.length; d++) {
  const day = windowStart.plus({ days: d });
  const dayKey = DAYS[day.weekday - 1];
  if (search.daysFilter && !search.daysFilter.includes(dayKey)) continue;
  const openings = cfg.hours[dayKey] ?? [];
  if (openings.length === 0) continue;

  const len = svc.lengths[idx];
  const startAt = day.set({ hour: hh, minute: mm, second: 0, millisecond: 0 });
  const endAt = startAt.plus({ minutes: len });
  const startMin = startAt.hour * 60 + startAt.minute;
  const endMin = endAt.hour * 60 + endAt.minute;

  const fitsHours = openings.some(([a, z]) => startMin >= a && endMin <= z);
  if (!fitsHours) continue;
  if (startAt.toMillis() < earliest) continue;
  if (overlaps(startAt.toMillis(), endAt.toMillis())) continue;

  sessions.push({ index: idx, date: startAt.toFormat('yyyy-MM-dd'), startIso: startAt.toISO(), endIso: endAt.toISO(), lengthMin: len });
  idx++;
}

return [{ json: { meta, req, cfg, svc, sessions, allFound: sessions.length === svc.lengths.length } }];

const { meta, req, sessions, svc } = $input.first().json;
const foundCount = sessions.length;
const msg = foundCount > 0
  ? `I could only find ${foundCount} of the ${svc.lengths.length} sessions needed in that window. Would you like to try a different start date, time, or spread of days?`
  : "I couldn't find any available sessions in that window. Would you like to try a different start date or time?";
return [{ json: { meta, req, res: { action: req.action, http: 200, category: 'package_no_availability', msg } } }];

const { meta, req, sessions, svc } = $input.first().json;
const list = sessions.map(s => `${s.date} ${s.startIso.slice(11,16)}`).join(', ');
return [{ json: { meta, req, res: { action: 'check_package_availability', http: 200, category: 'ok', body: {
  available: true,
  sessions: sessions.map(s => ({ date: s.date, start: s.startIso.slice(11,16), end: s.endIso.slice(11,16) })),
  price: svc.price,
  message: `${sessions.length} sessions available: ${list}. Total price: £${svc.price}.`
} } } }];

const { req, cfg, svc, sessions, meta } = $input.first().json;
const now = DateTime.now().setZone(cfg.tz).toISODate();
const packageTag = [cfg.business_id, req.customer_phone, svc.name.toLowerCase().trim(), req.start_date].join('|');
return sessions.map(sess => ({ json: {
  meta, req, cfg, svc, sess, package_tag: packageTag,
  key_material: [cfg.business_id, req.customer_phone, svc.name.toLowerCase().trim(), req.start_date, sess.index, now].join('|')
} }));

const items = $input.all();
return items.map(it => {
  const { req, cfg, svc, sess, booking_key, package_tag, meta } = it.json;
  const description = [
    `Customer Name: ${req.customer_name}`,
    `Customer Phone: ${req.customer_phone}`,
    `Customer Email: ${req.customer_email ?? ''}`,
    `Business ID: ${cfg.business_id}`,
    `Service: ${svc.name}`,
    `Package ID: ${package_tag}`,
    `Session: ${sess.index + 1} of ${svc.lengths.length}`
  ].join('\n');
  return { json: { meta, req, cfg, svc, sess, booking_key,
    q: { url: `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(cfg.calendar_id)}/events` },
    event: {
      id: booking_key,
      summary: `${svc.name} (session ${sess.index + 1}/${svc.lengths.length}) - ${req.customer_name}`,
      description,
      start: { dateTime: sess.startIso, timeZone: cfg.tz },
      end: { dateTime: sess.endIso, timeZone: cfg.tz }
    }
  } };
});

const ctxItems = $('Build Package Event Payload').all();
const respItems = $input.all();
const meta = ctxItems[0]?.json.meta;
const req = ctxItems[0]?.json.req;
const svc = ctxItems[0]?.json.svc;

const results = respItems.map((r, i) => {
  const ctx = ctxItems[i]?.json ?? {};
  const code = Number(r.json.statusCode);
  const body = r.json.body ?? {};
  const ok = code === 200 && body.status === 'confirmed' && body.id === ctx.booking_key;
  return { ok, sess: ctx.sess, booking_key: ctx.booking_key, appointment_id: body.id, deleteUrl: ctx.q ? `${ctx.q.url}/${ctx.booking_key}` : null };
});

const allOk = results.every(r => r.ok);

if (allOk) {
  const sessions = results.map(r => ({ date: r.sess.date, start: r.sess.startIso.slice(11,16), end: r.sess.endIso.slice(11,16), appointment_id: r.appointment_id }));
  return [{ json: {
    meta, req,
    res: { action: 'book_package_appointment', http: 200, category: 'ok', body: {
      success: true, message: `Your ${svc.name} package is booked: ${sessions.length} sessions starting ${req.start_date}. Total price: £${svc.price}.`, price: svc.price, sessions
    } },
    needRollback: false, toDelete: []
  } }];
}

const toDelete = results.filter(r => r.ok).map(r => r.deleteUrl).filter(Boolean);
return [{ json: {
  meta, req,
  res: { action: 'book_package_appointment', http: 503, category: 'partial_package_booking_failure', msg: "I wasn't able to book the full package — some sessions couldn't be reserved. Let me have the business call you to sort out the schedule." },
  needRollback: toDelete.length > 0, toDelete
} }];

const items = $input.all();
const first = items[0]?.json ?? {};
return [{ json: { meta: first.meta, req: first.req, res: first.res } }];
